-- Rifts World Book 3: England - the Mystic Herbology skill and 31 gear rows: Scathach magic cauldrons, irons and wood, the Elixir of Power and Deceit, Caliber X, New Camelot horse bionics and Eternal Spring water
-- 31 gear rows, 1 skills row.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~274-england-skill-and-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('scathach-magic-boiling-cauldron', 'Scathach Magic Boiling Cauldron', 'rifts', 'magic', NULL, 30000, 'Black Market Cost: 30,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Cool to the touch on the outside, but food or liquid poured inside becomes boiling hot on the inside without a fire beneath it. 450 P.P.E. to enchant. As with every Scathach magic cauldron: iron, entirely hand-crafted by a Scathach druid over months, each of three construction stages needing 133 P.P.E. at a place of magic at a time of peak energy; any size from an average pot to a five gallon kettle, with 2D4x10 M.D.C. if small or 2D4x100 M.D.C. if large, destroyed at zero. Rarely sold.', 'Rifts World Book 3: England p.41', NULL),
  ('scathach-magic-cauldron-of-destruction', 'Scathach Magic Cauldron of Destruction', 'rifts', 'magic', NULL, 80000000, 'Black Market Cost: 80 million credits to as much as ten times higher; very rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Any magic item, indestructible rune weapons included, heated inside it melts into worthless slag or ash, but only at a ley line nexus on the winter or summer solstice or during a lunar or partial solar eclipse. Most items are destroyed within one hour; rune weapons must bake 1D4+1 hours. 1,600 P.P.E. to enchant; the Scathach must be tenth level or higher to make it. As with every Scathach magic cauldron: iron, entirely hand-crafted by a Scathach druid over months, each of three construction stages needing 133 P.P.E. at a place of magic at a time of peak energy; any size from an average pot to a five gallon kettle, with 2D4x10 M.D.C. if small or 2D4x100 M.D.C. if large, destroyed at zero.', 'Rifts World Book 3: England p.41', NULL),
  ('scathach-cauldron-of-endless-water', 'Scathach Cauldron of Endless Water', 'rifts', 'magic', NULL, 40000, 'Black Market Cost: 40,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Always looks empty, but a glass, mug or other container dipped or placed inside comes out filled with fresh, cool water. 600 P.P.E. to enchant. As with every Scathach magic cauldron: iron, entirely hand-crafted by a Scathach druid over months, each of three construction stages needing 133 P.P.E. at a place of magic at a time of peak energy; any size from an average pot to a five gallon kettle, with 2D4x10 M.D.C. if small or 2D4x100 M.D.C. if large, destroyed at zero.', 'Rifts World Book 3: England p.41', NULL),
  ('scathach-magic-cauldron-of-plenty', 'Scathach Magic Cauldron of Plenty', 'rifts', 'magic', NULL, 300000, 'Black Market Cost: 300,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Food or drink cooked in it feeds ten times as many people as a normal cauldron its size; merely placing food inside changes nothing, it must be cooked there. 700 P.P.E. to enchant. As with every Scathach magic cauldron: iron, entirely hand-crafted by a Scathach druid over months, each of three construction stages needing 133 P.P.E. at a place of magic at a time of peak energy; any size from an average pot to a five gallon kettle, with 2D4x10 M.D.C. if small or 2D4x100 M.D.C. if large, destroyed at zero.', 'Rifts World Book 3: England p.41', NULL),
  ('scathach-magic-cauldron-of-purity', 'Scathach Magic Cauldron of Purity', 'rifts', 'magic', NULL, 150000, 'Black Market Cost: 150,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Anything cooked in it is safe to eat or drink: it destroys poisons, dangerous chemicals, pollutants, disease and magic present beforehand. Magic herbs and potions cooked in it are negated and made useless. 800 P.P.E. to enchant. As with every Scathach magic cauldron: iron, entirely hand-crafted by a Scathach druid over months, each of three construction stages needing 133 P.P.E. at a place of magic at a time of peak energy; any size from an average pot to a five gallon kettle, with 2D4x10 M.D.C. if small or 2D4x100 M.D.C. if large, destroyed at zero.', 'Rifts World Book 3: England p.41', NULL),
  ('scathach-magic-chains', 'Scathach Magic Chains', 'rifts', 'magic', NULL, 500, 'Black Market Cost: 500 credits per one foot (0.3 m) length of chain', NULL, 0, NULL, NULL, NULL, NULL, NULL, 10, 'Magic iron. Never bends, dulls or rusts; only a supernatural P.S. of 40 or higher can break a link. Each link has 10 M.D.C. 10 P.P.E. to enchant each link. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-hammer', 'Scathach Magic Hammer', 'rifts', 'weapon', NULL, 8000, 'Black Market Cost: 8,000 credits', '2D4 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic iron. Never bends, dulls or breaks, and is impervious to even mega-damage fire and heat. Inflicts 2D4 S.D.C. used as a weapon. 110 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-horseshoes', 'Scathach Magic Horseshoes', 'rifts', 'magic', NULL, 40000, 'Black Market Cost: 40,000 credits a pair', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic iron. The horse wearing them runs 25% faster, can exert itself twice as long before exhaustion, and leaps ten feet (3 m) higher and farther. 100 P.P.E. to enchant each shoe. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-javelin', 'Scathach Magic Javelin (iron)', 'rifts', 'weapon', NULL, 15000, 'Black Market Cost: 15,000 credits', '3D6 S.D.C. to mortal foes; 3D6 M.D. to supernatural foes and creatures of magic', 0, NULL, NULL, NULL, NULL, NULL, 100, 'Magic iron. Never bends, dulls or rusts. Inflicts 3D6 S.D.C. to mortal foes but 3D6 M.D. against supernatural foes and creatures of magic. The javelin itself has 100 M.D.C. 250 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-mallet', 'Scathach Magic Mallet (large)', 'rifts', 'weapon', NULL, 12000, 'Black Market Cost: 12,000 credits', '2D6 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic iron; a bigger version of the Magic Hammer. Never bends, dulls or breaks, is amazingly lightweight for its size and is impervious to even mega-damage fire and heat. Inflicts 2D6 S.D.C. used as a weapon. 200 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-manacles', 'Scathach Magic Manacles', 'rifts', 'magic', NULL, 200000, 'Black Market Cost: 200,000 credits per set', NULL, 0, NULL, NULL, NULL, NULL, NULL, 100, 'Magic iron. The lock cannot be picked, even by magical means such as the Escape spell, and only a supernatural P.S. of 50 or higher can force them open. Never rust; 100 M.D.C. 500 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-nails', 'Scathach Magic Nails', 'rifts', 'magic', NULL, 30, 'Black Market Cost: 30 credits a dozen', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic iron. Never bend or rust. 5 P.P.E. to enchant each nail. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-spikes', 'Scathach Magic Spikes', 'rifts', 'magic', NULL, 50, 'Black Market Cost: 50 credits for a half dozen', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic iron. Indestructible; never dull or bend. 10 P.P.E. to enchant each one. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-sword', 'Scathach Magic Sword', 'rifts', 'weapon', NULL, 25000, 'Black Market Cost: 25,000 credits', '2D6 S.D.C. to mortal foes, double to mortal forces of evil; 2D6 M.D. to creatures of magic and the supernatural', 0, NULL, NULL, NULL, NULL, NULL, 80, 'Magic iron. Indestructible and never dulls; +1 to strike and parry. Inflicts 2D6 S.D.C. to mortal foes, double damage to mortal forces of evil, and 2D6 M.D. to creatures of magic and the supernatural. The sword has 80 M.D.C. 270 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-throwing-iron', 'Scathach Magic Throwing Iron', 'rifts', 'weapon', NULL, 10000, 'Black Market Cost: 10,000 credits each', '2D4 S.D.C. to mortal opponents; 2D6 M.D. to creatures of magic and supernatural beings, vampires included', 0, NULL, NULL, NULL, NULL, NULL, 40, 'Magic iron. Never dulls or bends. Inflicts 2D4 S.D.C. to mortal opponents, but 2D6 M.D. to creatures of magic and supernatural beings, including vampires. The iron has 40 M.D.C. 200 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-hawthorn-arrow', 'Scathach Magic Arrow (Hawthorn)', 'rifts', 'weapon', NULL, 50, 'Market Value: 50 credits per arrow', '2D4 S.D.C. to normal creatures; 1D4x10 M.D. to vampires; 2D6 M.D. to zombies, mummies and other animated dead or undead', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood. Inflicts 2D4 S.D.C. to normal creatures, 1D4x10 M.D. to vampires, and 2D6 M.D. to zombies, mummies and other animated dead or undead. 10 P.P.E. to enchant each arrow. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-alder-arrow', 'Scathach Magic Arrow (Alder)', 'rifts', 'weapon', NULL, 1500, 'Market Value: 1500 credits per arrow', '2D4 S.D.C. to normal creatures; 6D6 M.D. to air elementals', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood. Inflicts 2D4 S.D.C. to normal creatures, but 6D6 M.D. to air elementals. 60 P.P.E. to enchant each arrow. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-cedar-arrow', 'Scathach Magic Arrow (Cedar)', 'rifts', 'weapon', NULL, 500, 'Market Value: 500 credits per arrow', '2D4 S.D.C. to normal creatures; 6D6 M.D. to energy beings and entities', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood. Inflicts 2D4 S.D.C. to normal creatures, but 6D6 M.D. to energy beings and entities. 40 P.P.E. to enchant each arrow. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-oak-arrow', 'Scathach Magic Arrow (Oak)', 'rifts', 'weapon', NULL, 100, 'Market Value: 100 credits per arrow', '+6 S.D.C. over the arrow''s normal damage', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood; strong and stable. +1 to strike, flies twice as far as normal and inflicts an extra +6 S.D.C. 30 P.P.E. to enchant each arrow. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-pine-bow', 'Scathach Magic Bow (pine)', 'rifts', 'weapon', NULL, 2000, 'Market Value: 2000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood. The bow and its string never break, and every arrow launched from it flies straight and sure: +1 on initiative, +1 to strike. 80 P.P.E. to enchant the bow. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-flute', 'Scathach Magic Flute', 'rifts', 'magic', NULL, 3000, 'Market Value: 3000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood. Music played on it always sounds of professional quality. 120 P.P.E. to enchant the flute. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-war-hammer', 'Scathach Magic War Hammer', 'rifts', 'weapon', NULL, 3000, 'Market Value: 3000 credits', '4D6 S.D.C. to mortal foes; 2D6 M.D. to supernatural foes; 4D6 M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Weapon of wood, made of oak and iron and surprisingly lightweight. Inflicts 4D6 S.D.C. to mortal foes, 2D6 M.D. to supernatural foes and 4D6 M.D. to vampires; +1 to strike and parry. 220 P.P.E. to enchant. The printed P.P.E. line reads 220 points to enchant the flute, apparently a slip carried from the Magic Flute entry above it; the figure is stored as printed. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('scathach-magic-throwing-stick', 'Scathach Magic Throwing Stick', 'rifts', 'weapon', NULL, 10000, 'Black Market Cost: 10,000 credits each', '1D6 S.D.C. to mortal opponents; 2D6 M.D. to creatures of magic and supernatural beings, vampires included', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic wood. Never breaks or bends. Inflicts 1D6 S.D.C. to mortal opponents, but 2D6 M.D. to creatures of magic and supernatural beings, including vampires. 180 P.P.E. to enchant. Rare, especially away from the British Isles.', 'Rifts World Book 3: England p.42', NULL),
  ('chiang-ku-elixir-of-power-and-deceit', 'Elixir of Power and Deceit', 'rifts', 'magic', NULL, 300000, 'Most Chiang-Ku charge 3D4x100,000 credits for each drink/power, and frequently two to ten times more for the most coveted powers; may be nearly free or a gift to someone the maker wants to control', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A magic potion, brewed as a tea or similar drink, whose secret only anarchist and evil Chiang-Ku dragons use; it is never taught to another race. Each drink grants one super ability for only two weeks, with an emotional high. Only one power at a time, and no power may be chosen more than twice. The twelve powers available: Control Fire (ignite fire, fuel flame, fire bolt and circle of flame; fire does half damage; each use one melee action); Control Wind (breathe without air, float in air, wind rush); Dragon Strength (P.S. 25, supernatural, punches and kicks inflict mega-damage); Fly (as wingless flight or the fly like an eagle spell); Impervious to Fire (even mega-damage fire and heat do nothing); Invisibility (at will, indefinitely, with what he wears and carries, but not other people or human-sized objects; visible if asleep, knocked out or killed); Invulnerability (as the super power or spell, nonstop); Man of Metal (alter physical structure: metal, 600 M.D.C. and supernatural strength); Man of Stone (alter physical structure: stone, 450 M.D.C. and supernatural strength); Man of Shadows (darkness control, or the equivalent of nightvision and shadow meld); Project Energy (5D6 M.D. bolt from the eyes or hands, range 600 feet/183 m, each blast one attack); Underwater Abilities (swim as a fish (superior) and nightvision). Cumulative and indefinite with each drink: -1 to save vs the brewer''s magic, -1 to save vs his psionic attacks and mind control, and 10% more likely to trust and obey him; after nine drinks (six if the brewer has M.A. 20 or higher) the drinker does anything asked, saving only when told to kill himself or hurt a loved one. No limit to how many can be controlled. Broken only by forcing the maker to drink his own brew, which frees all of his minions; an anti-magic cloud negates it only while it lasts. Does not work on dragons.', 'Rifts World Book 3: England p.49-50', NULL),
  ('caliber-x', 'Caliber X', 'rifts', 'weapon', NULL, 250000, 'Black Market Value: 250,000 credits as a collector''s item; would skyrocket for someone else able to use it', '2D4 M.D. as a vibro short sword, 1D4 M.D. from the spiked handle; psi-sword 1D6 M.D. per level of experience; bolts of force 4D6 S.D.C., 2D4x10 S.D.C., 1D6, 2D6 or 3D6 M.D.', 1, 'Bolts of force 100 feet (30.5 m) per level of experience; thrown 25 feet (7.6 m) per level of experience', NULL, NULL, NULL, NULL, 300, 'A surviving pre-Rifts British psionic amplification weapon, a vibro short sword with a gun-barrel section, carried by King Arr''thuu of New Camelot. It attunes automatically to a user whose mental frequency matches (a one in ten million chance), reacts to his thoughts and can be sensed like dowsing within 200 miles (320 km). Psi-sword: a thought and 5 I.S.P. make it a psi-sword twice the size for 15 minutes per level, 1D6 M.D. per level, able to slice through anything including magic barriers (15% chance of dispelling them); its energy aura absorbs all damage to the weapon and engages automatically when it or its owner is in danger. Bolts of force: 4D6 S.D.C., 2D4x10 S.D.C., or 1D6, 2D6 or 3D6 M.D., +3 to strike, 1 I.S.P. per blast. Telekinetic: thrown and guided at +5 to strike (P.P. bonuses do not apply) and returns, the return a melee action, 1 I.S.P. per toss. Mega-damage alloy with 300 M.D.C.; takes no damage from ordinary combat. Mrrlyn holds two others.', 'Rifts World Book 3: England p.106-107', NULL),
  ('england-horse-cybernetics-package', 'Horse Cybernetics Package (New Camelot)', 'rifts', 'cybernetics', NULL, 50000, 'Cost: 50,000 to 60,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The usual cybernetics for horses near New Camelot (Grydonfield Stables, six miles west, and the Bionic Centre on Techno Haven): enhanced vision (polarized and passive nightvision), ear and head implants so the horse can hear and respond to radio messages or signals, sound filtration so loud noises do not spook it, an identity implant to prove ownership, and a homing implant so a stray can be found. A toxic filter or oxygen storage cell can be added for 55,000 credits each.', 'Rifts World Book 3: England p.113', NULL),
  ('england-horse-toxic-filter', 'Horse Toxic Filter (New Camelot)', 'rifts', 'cybernetics', NULL, 55000, 'An additional 55,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An add-on to the basic horse cybernetics package sold near New Camelot (Grydonfield Stables and the Bionic Centre).', 'Rifts World Book 3: England p.113', NULL),
  ('england-horse-oxygen-storage-cell', 'Horse Oxygen Storage Cell (New Camelot)', 'rifts', 'cybernetics', NULL, 55000, 'An additional 55,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An add-on to the basic horse cybernetics package sold near New Camelot (Grydonfield Stables and the Bionic Centre).', 'Rifts World Book 3: England p.113', NULL),
  ('england-basic-bionic-horse', 'Basic Bionic Horse (partial reconstruction, New Camelot)', 'rifts', 'vehicle', NULL, 280000, 'Cost: 280,000 credits; the Bionic Centre can make bionic horses for about 10% less', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'Robot legs and reinforced head, neck and body (main body 50 M.D.C.), special barding adding 100 M.D.C., plus the basic horse cybernetic implants. Typical speed 60 mph (96.5 km). Sold at Grydonfield Stables near New Camelot, which keeps 1D6 bionic horses.', 'Rifts World Book 3: England p.113', NULL),
  ('england-full-feature-bionic-horse', 'Full Feature Bionic Horse (New Camelot)', 'rifts', 'vehicle', NULL, 2000000, 'Cost: two to three million credits; the Bionic Centre can make bionic horses for about 10% less', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'More complete bionic reconstruction: speed 120 mph (192 km), heavier barding (300 M.D.C.), all the basic horse cybernetic systems plus bionic lungs with gas filter and oxygen storage tank (2 hour supply), a bionic heart, four medium and two large hidden compartments, and one concealed weapon rod of choice (the larger leg variety) in the forward body, powered by the horse and used by the rider. Further reasonable features such as a computer or gyro-compass can be added. Many prefer it to a robot horse because it keeps the personality, loyalty and traits of a real horse. Sold at Grydonfield Stables near New Camelot.', 'Rifts World Book 3: England p.113', NULL),
  ('eternal-spring-water', 'Eternal Spring Water (Bath)', 'rifts', 'magic', NULL, 2, '2 credits an ounce (28 g) for healers, druids, herbalists, priests, the occasional practitioner of magic and royalty (an eight ounce glass is 16 credits); anyone else petitions the courts (usually 120 credits in fees) and pays twice that, 4 credits an ounce. Bathing costs 20 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Water drawn from the warm magic spring at Bath, held by the Eternal City. Herbalists and woodland druids can transform it into holy water (10 P.P.E.), a cure to negate poison (20 P.P.E.), or superior wine (20 P.P.E.); it is easily purified (10 P.P.E.) and often used in potions and teas, especially those that heal or purify. Bathing in the spring relieves aches, headaches and congestion, restores P.P.E. and I.S.P. at twice the normal rate, leaves bathers rested after half an hour to an hour, and makes them heal three times faster over the next 24 hours. The springs seem magically protected from poisoning or pollution.', 'Rifts World Book 3: England p.117-118', NULL);

INSERT OR IGNORE INTO skills (name, category, base, base_formula, per_level, systems, source, source_book, note, bonuses, level_bonuses) VALUES
  ('Mystic Herbology', 'Medical', 20, NULL, 5, '["rifts"]', 'import', 'Rifts World Book 3: England p.22-23', 'Far more complete than Holistic Medicine: where to find magic and medicinal herbs, when to pick them, how to prepare, dry and preserve them, poisons, plant lore and legends, magical properties, protection against the supernatural, instilling an herb with magic, and making ordinary and magic teas, tonics, elixirs, potions, salves and balms. A failed roll means the treatment is flawed and will not work. A closely guarded secret known only to the Herbalist O.C.C. and certain druid O.C.C.s; only the druids can make wands, staves and other items empowered by magic herbs. Base Skill 20% +5% per level of experience; each class''s printed bonus goes on its own grant.', NULL, NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 31 gear rows are in' AS assertion, count(*) AS got, 31 AS want
  FROM gear WHERE slug IN ('scathach-magic-boiling-cauldron', 'scathach-magic-cauldron-of-destruction', 'scathach-cauldron-of-endless-water', 'scathach-magic-cauldron-of-plenty', 'scathach-magic-cauldron-of-purity', 'scathach-magic-chains', 'scathach-magic-hammer', 'scathach-magic-horseshoes', 'scathach-magic-javelin', 'scathach-magic-mallet', 'scathach-magic-manacles', 'scathach-magic-nails', 'scathach-magic-spikes', 'scathach-magic-sword', 'scathach-magic-throwing-iron', 'scathach-magic-hawthorn-arrow', 'scathach-magic-alder-arrow', 'scathach-magic-cedar-arrow', 'scathach-magic-oak-arrow', 'scathach-magic-pine-bow', 'scathach-magic-flute', 'scathach-magic-war-hammer', 'scathach-magic-throwing-stick', 'chiang-ku-elixir-of-power-and-deceit', 'caliber-x', 'england-horse-cybernetics-package', 'england-horse-toxic-filter', 'england-horse-oxygen-storage-cell', 'england-basic-bionic-horse', 'england-full-feature-bionic-horse', 'eternal-spring-water') AND source_book IS NOT NULL;
SELECT 'all 1 skills rows are in' AS assertion, count(*) AS got, 1 AS want
  FROM skills WHERE name IN ('Mystic Herbology') AND source_book IS NOT NULL;

